def min_window(s, t):
    char_count = {c: 0 for c in t}
    min_len = len(s) + 1
    start, end = 0, 0
    result = ""
    while end < len(s):
        char = s[end]
        char_count[char] += 1
        if char in char_count and char_count[char] == 1:
            min_len = min(min_len, end - start + 1)
        end += 1
        while end - start > 0:
            char = s[start]
            char_count[char] -= 1
            if char in char_count and char_count[char] == 0:
                del char_count[char]
            start += 1
            if end - start < min_len:
                min_len = end - start + 1
                result = s[start:end + 1]
    return "" if min_len > len(s) else result
